cd /tmp/shot && cat > shot.mjs <<'EOF'
import { chromium } from 'playwright';
import { spawn } from 'node:child_process';
const PORT = 4917;
const srv = spawn('npx', ['vite', 'preview', '--port', String(PORT), '--strictPort'], { cwd: '/home/sandbox/workspace', stdio: ['ignore', 'pipe', 'pipe'] });
srv.stdout.on('data', d => process.stdout.write('[vite] ' + d));
srv.stderr.on('data', d => process.stdout.write('[vite-err] ' + d));
let up = false;
for (let i = 0; i < 60 && !up; i++) { try { const r = await fetch(`http://localhost:${PORT}/`); up = r.ok; } catch { await new Promise(r => setTimeout(r, 500)); } }
if (!up) { console.log('server did not start'); srv.kill(); process.exit(1); }
const browser = await chromium.launch({ args: ['--no-sandbox'] });
const page = await browser.newPage({ viewport: { width: 960, height: 600 } });
page.on('pageerror', e => console.log('PAGEERROR', e.message));
page.on('console', m => m.type() === 'error' && console.log('CONSOLE', m.text().slice(0, 300)));
await page.goto(`http://localhost:${PORT}/`);
await page.waitForSelector('svg[role=img]');
await page.evaluate(() => document.fonts.ready);
await page.waitForTimeout(300);
console.log('title-present', await page.getByText('Активные пользователи').count(), 'bodyClass', await page.evaluate(() => document.body.className));
console.log('strokes', await page.$$eval('svg[role=img] path', ps => ps.map(p => p.getAttribute('stroke'))));
await page.screenshot({ path: '/tmp/shot/light.png' });
const box = await page.locator('svg[role=img] rect').boundingBox();
await page.mouse.move(box.x + box.width * 0.72, box.y + 100);
await page.waitForTimeout(100);
await page.screenshot({ path: '/tmp/shot/light-hover.png' });
await page.locator('label', { hasText: 'Тёмная' }).click();
await page.waitForTimeout(300);
console.log('bodyClass after toggle', await page.evaluate(() => document.body.className));
console.log('strokes dark', await page.$$eval('svg[role=img] path', ps => ps.map(p => p.getAttribute('stroke'))));
await page.screenshot({ path: '/tmp/shot/dark.png' });
await page.mouse.move(box.x + box.width * 0.72, box.y + 100);
await page.waitForTimeout(100);
await page.screenshot({ path: '/tmp/shot/dark-hover.png' });
// keyboard: focus hit area and press ArrowLeft twice
await page.mouse.move(5, 5);
await page.locator('svg[role=img] rect').focus();
await page.keyboard.press('ArrowLeft'); await page.keyboard.press('ArrowLeft');
await page.waitForTimeout(100);
await page.screenshot({ path: '/tmp/shot/dark-keyboard.png' });
await page.locator('button', { hasText: 'Таблица' }).click();
await page.waitForTimeout(200);
await page.screenshot({ path: '/tmp/shot/dark-table.png' });
await browser.close(); srv.kill(); process.exit(0);
EOF
